package com.example.com.englishai.backend.infrastructure.persistence.entity; import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="password_reset_codes") public class PasswordResetCodeEntity { @Id private UUID id; @Column(name="user_id",nullable=false) private UUID userId; @Column(name="code_hash",nullable=false,length=64) private String codeHash; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; @Column(name="expires_at",nullable=false) private OffsetDateTime expiresAt; @Column(name="used_at") private OffsetDateTime usedAt; @Column(name="invalidated_at") private OffsetDateTime invalidatedAt; @Column(nullable=false) private int attempts; @Column(name="max_attempts",nullable=false) private int maxAttempts; protected PasswordResetCodeEntity(){} public PasswordResetCodeEntity(UUID i,UUID u,String h,OffsetDateTime c,OffsetDateTime e,OffsetDateTime used,OffsetDateTime inv,int a,int m){id=i;userId=u;codeHash=h;createdAt=c;expiresAt=e;usedAt=used;invalidatedAt=inv;attempts=a;maxAttempts=m;} public UUID getId(){return id;}public UUID getUserId(){return userId;}public String getCodeHash(){return codeHash;}public OffsetDateTime getCreatedAt(){return createdAt;}public OffsetDateTime getExpiresAt(){return expiresAt;}public OffsetDateTime getUsedAt(){return usedAt;}public OffsetDateTime getInvalidatedAt(){return invalidatedAt;}public int getAttempts(){return attempts;}public int getMaxAttempts(){return maxAttempts;} }
